import test from 'node:test';
import assert from 'node:assert/strict';
import { getCustomer, listCustomers, mergeCustomers, normalizeId } from '../src/customers.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('normalizeId trims and uppercases', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
  assert.equal(normalizeId('  C-002  '), 'C-002');
  assert.equal(normalizeId('c-003'), 'C-003');
});

test('getCustomer finds customer by normalized id', () => {
  const result = getCustomer('c-001');
  assert.equal(result.ok, true);
  assert.equal(result.value.id, 'C-001');
});

test('getCustomer returns error for unknown customer', () => {
  const result = getCustomer('UNKNOWN');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('listCustomers returns all customers', () => {
  const customers = listCustomers();
  assert(customers.length > 0);
  assert(customers.find((c) => c.id === 'C-001'));
  assert(customers.find((c) => c.id === 'C-002'));
});

test('mergeCustomers removes fromId and reassigns invoices', () => {
  const customers = listCustomers();

  // Create invoices for C-002 and C-003
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const inv2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const invoices = [inv1.value, inv2.value];

  // Merge C-002 into C-003
  const result = mergeCustomers(customers, invoices, 'C-002', 'C-003');

  assert.equal(result.ok, true);
  assert(result.value.customers.find((c) => c.id === 'C-003'));
  assert(!result.value.customers.find((c) => c.id === 'C-002'));
  assert.equal(result.value.invoices[0].customerId, 'C-003');
  assert.equal(result.value.invoices[1].customerId, 'C-003');
});

test('mergeCustomers returns CUSTOMER_NOT_FOUND for missing fromId', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'UNKNOWN', 'C-003');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers returns CUSTOMER_NOT_FOUND for missing intoId', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-002', 'UNKNOWN');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers returns SAME_CUSTOMER when both ids are the same', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-002', 'C-002');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers with case insensitive ids', () => {
  const customers = listCustomers();

  const inv = createInvoice({
    customerId: 'c-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const invoices = [inv.value];

  const result = mergeCustomers(customers, invoices, 'c-002', 'c-003');

  assert.equal(result.ok, true);
  assert(!result.value.customers.find((c) => c.id === 'C-002'));
  assert.equal(result.value.invoices[0].customerId, 'C-003');
});

test('mergeCustomers with multiple invoices from fromId', () => {
  const customers = listCustomers();

  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-08',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-09',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const invoices = [inv1.value, inv2.value, inv3.value];

  const result = mergeCustomers(customers, invoices, 'C-002', 'C-003');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-003');
  assert.equal(result.value.invoices[1].customerId, 'C-003');
  assert.equal(result.value.invoices[2].customerId, 'C-003');
});

test('mergeCustomers preserves invoice structure', () => {
  const customers = listCustomers();

  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
    terms: 'NET14',
  });

  const invoices = [inv.value];

  const result = mergeCustomers(customers, invoices, 'C-002', 'C-003');

  assert.equal(result.ok, true);
  const mergedInv = result.value.invoices[0];
  assert.equal(mergedInv.issueDate, '2025-10-07');
  assert.equal(mergedInv.status, 'draft');
  assert.equal(mergedInv.terms, 'NET14');
  assert.equal(mergedInv.lines.length, 1);
});

test('mergeCustomers with issued invoices', () => {
  const customers = listCustomers();

  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const issued = issueInvoice(inv.value, []).value;
  const invoices = [issued];

  const result = mergeCustomers(customers, invoices, 'C-002', 'C-003');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-003');
  assert.equal(result.value.invoices[0].status, 'issued');
  assert(result.value.invoices[0].number);
});

test('mergeCustomers does not mutate original arrays', () => {
  const customers = listCustomers();
  const originalCustomersLength = customers.length;

  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const invoices = [inv.value];
  const originalInvoicesLength = invoices.length;

  const result = mergeCustomers(customers, invoices, 'C-002', 'C-003');

  assert.equal(result.ok, true);
  // Original arrays should not be modified
  assert.equal(customers.length, originalCustomersLength);
  assert.equal(invoices.length, originalInvoicesLength);
  assert.equal(invoices[0].customerId, 'C-002');
});

test('mergeCustomers with empty invoice array', () => {
  const customers = listCustomers();

  const result = mergeCustomers(customers, [], 'C-002', 'C-003');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert(!result.value.customers.find((c) => c.id === 'C-002'));
});

test('mergeCustomers merges all customer data', () => {
  const customers = listCustomers();

  const fromCustomer = customers.find((c) => c.id === 'C-002');
  const intoCustomer = customers.find((c) => c.id === 'C-003');

  const result = mergeCustomers(customers, [], 'C-002', 'C-003');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, customers.length - 1);
  assert(result.value.customers.find((c) => c.id === 'C-003'));
  assert(!result.value.customers.find((c) => c.id === 'C-002'));
});

